callin-technical-code:
:is(.markdown-preview-view, .markdown-source-view){margin-top:12px;border-top:1px solid var(--background-modifier-border);padding-top:10px}
:is(.markdown-preview-view, .markdown-source-view) h4{font-size:calc(var(--h4-size) * 0.526094);text-transform:uppercase;letter-spacing:.1em;color:var(--text-muted);margin:16px 0 5px}
:is(.markdown-preview-view, .markdown-source-view) pre{font:11px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--background-primary);padding:12px;border-radius:3px;max-height:450px;overflow:auto;margin:0}
:is(.markdown-preview-view, .markdown-source-view) .hint{font-size:calc(var(--font-text-size) * 0.6875);color:var(--text-muted)}
@media print{
 :is(.markdown-preview-view, .markdown-source-view){display:none!important}
}
:is(.markdown-preview-view, .markdown-source-view) .callout-content pre {padding:.8em;background:var(--background-primary);border:1px solid var(--background-modifier-border);border-radius:.35em;overflow:auto;font-size:.78em}

callout-technical-print:
